"""Drafter training traces generated by the target with vLLM, over a file-locked work queue.

Every pool prompt gets one greedy response; --sampled-fraction adds one sampled response to a
SHA256-selected share of prompts, with the family's sampling settings split by prompt hash. The
budget is prompt + output tokens with natural EOS. A response that falls into a loop is stopped
online at the loop onset (loop_onset below) and saved up to that onset with finish_reason "loop",
so no budget is spent on the repetition.

--variant w64 is the shared-KV checkpoint served with its trained read rule (native single-pass
prompt, last-loop KV outside the W-token local window); the vLLM fork applies it because the
checkpoint's config.json declares loopedtf_kv_policy / loopedtf_kv_window (training.kd.fix_config
adds them to older exports; --kv-policy forces them through hf_overrides for a checkpoint that
lacks them). --variant original is the per-loop-KV original model. Both drafters of a model in the
paper train on the w64 traces. Dory shares without adaptation: both variants are its pinned
checkpoint with the fork's configuration overrides (vllm.v1.spec_decode.twodsd.dory_kv_policy: R = 4
loops, per-loop KV, and for w64 last-loop sharing with W = 64 on the full-attention layers), and its
engine compiles (VLLM_COMPILE, as in the paper's Dory measurements; the others run CUDA graphs only).
Ouro uses the pool's rendered IDs; Nanbeige and Dory re-render the same text with their native
template, thinking on, and Nanbeige's system turn. vLLM cannot preempt a shared request, so
admission reserves each request's full budget on the engine's actual cache groups.

  launch   build the queue in --out and start one detached worker per GPU
  join     start workers on more GPUs for the existing queue
  worker   (internal) one GPU
  status   progress
  requeue  once every worker of the queue has exited, re-queue claimed but unfinished requests
  collect  per-pool trace files (<pool>.jsonl, manifest.json) once the queue is drained
Touch OUT/queue/stop (all) or OUT/queue/stop-gpuN to stop claiming; workers drain and exit.
Requests a stopped or failed worker had claimed but not finished stay unfinished until requeue + join.

  python -m training.drafter.traces launch --out TRACES --model ouro-1.4b-thinking --variant w64 \\
      --target-path W64_CHECKPOINT --prompts PROMPTS_V2 --gpus 0 1 2 3 4 5 6 7
"""
from __future__ import annotations

import argparse
import fcntl
import hashlib
import json
import math
import os
import subprocess
import sys
import tempfile
import time
from contextlib import ExitStack, contextmanager
from pathlib import Path

from ..common import registry
from ..common.chat import eos_ids, load_tokenizer, ouro_turns, render_native, system_messages
from ..common.io import file_sha, locked, read_jsonl, read_jsonl_partial
from ..sharekv.policy import NATIVE, POLICY_KEY, SHARED, checkpoint_policy, config_keys

POOL_ORDER = ("dev", "eval", "train")
# Ouro's two recommended settings; Nanbeige's (thinking) generation_config; Dory and Inkling2: the paper's
# sampling (Inkling2's generation_config has temperature 1.0 and no nucleus).
SAMPLING = {"ouro": [{"temperature": 1.0, "top_p": 0.7, "top_k": 0}, {"temperature": 0.6, "top_p": 0.95, "top_k": 0}],
            "nanbeige": [{"temperature": 0.6, "top_p": 0.95, "top_k": 20}],
            "dory": [{"temperature": 0.6, "top_p": 0.95, "top_k": 0}],
            "inkling2": [{"temperature": 0.6, "top_p": 0.95, "top_k": 0}]}
LOOP_WINDOW, LOOP_NGRAM, LOOP_MIN_UNIQUE, LOOP_STRIDE = 1024, 16, 0.5, 64
# Upper bounds on concurrent requests; full-budget admission usually binds first.
MAX_SEQS = {"ouro-1.4b-thinking": 64, "ouro-2.6b-thinking": 48, "nanbeige4.2-3b": 96, "dory1.0-4b": 64}
GRAPH_ONLY = {"mode": 0, "cudagraph_mode": "FULL_DECODE_ONLY"}
# Dory's KV sharing per trace variant (dory_kv_policy names).
DORY_SHARING = {"w64": "w64", "original": "native"}


def unit(text):
    """Deterministic value in [0, 1) from a string."""
    return int(hashlib.sha256(text.encode()).hexdigest()[:15], 16) / 16 ** 15


def loop_onset(ids, start=0):
    """First stride-aligned p >= start whose next LOOP_WINDOW tokens have fewer than LOOP_MIN_UNIQUE
    distinct LOOP_NGRAM-grams; None if no complete window qualifies. Scanning a growing sequence
    from the last unchecked start finds the same onset as scanning the finished one."""
    grams = LOOP_WINDOW - LOOP_NGRAM + 1
    for p in range(start, len(ids) - LOOP_WINDOW + 1, LOOP_STRIDE):
        window = ids[p:p + LOOP_WINDOW]
        if len({tuple(window[i:i + LOOP_NGRAM]) for i in range(grams)}) < LOOP_MIN_UNIQUE * grams:
            return p
    return None


class LoopWatch:
    """Online loop_onset over a growing response; extend() returns the onset once a window shows it."""

    def __init__(self):
        self.ids, self.next = [], 0

    def extend(self, tokens):
        self.ids.extend(tokens)
        if len(self.ids) - self.next < LOOP_WINDOW:
            return None
        onset = loop_onset(self.ids, self.next)
        self.next += ((len(self.ids) - LOOP_WINDOW - self.next) // LOOP_STRIDE + 1) * LOOP_STRIDE
        return onset


def is_degenerate(output_ids, tail=512, n=16, min_unique=0.25):
    """A trace whose last `tail` tokens have fewer than min_unique distinct n-grams (excluded from training)."""
    if len(output_ids) < tail:
        return False
    t = output_ids[-tail:]
    grams = {tuple(t[i:i + n]) for i in range(len(t) - n + 1)}
    return len(grams) / (len(t) - n + 1) < min_unique


def worker_cache_layout(worker):
    """Read-only collective RPC: the engine's actual KV cache groups."""
    return [{"kind": type(group.kv_cache_spec).__name__,
             "block_size": group.kv_cache_spec.block_size,
             "window": getattr(group.kv_cache_spec, "sliding_window", None),
             "layers": len(group.layer_names)}
            for group in worker.model_runner.kv_cache_config.kv_cache_groups]


def reserved_blocks(request, layout, block_size):
    """Upper bound for complete decode and the transient native prompt prefill.

    Recent groups allocate all prompt blocks at prefill, then release blocks
    outside their window. Two extra blocks cover boundary alignment and growth.
    Full groups retain every position. Groups share a physical block pool.
    """
    if not layout or block_size < 1:
        raise ValueError("missing actual cache layout")
    full = math.ceil((request["prompt_tokens"] + request["max_new_tokens"]) / block_size)
    prompt = math.ceil(request["prompt_tokens"] / block_size)
    count = 0
    for group in layout:
        if group["block_size"] != block_size:
            raise ValueError("mixed block sizes need a separate admission bound")
        if group["kind"] == "FullAttentionSpec":
            count += full
        elif group["kind"] == "SlidingWindowSpec" and group["window"] > 0:
            count += max(prompt, math.ceil(group["window"] / block_size) + 2)
        else:
            raise ValueError(f"unvalidated cache group: {group}")
    return count


def target_policy(path, variant, requested="auto", window=64):
    """(effective KV policy, hf_overrides or None) of a target checkpoint for this trace variant.

    auto uses what config.json declares (no hf_overrides). A forced policy must agree with the
    checkpoint if it declares one; it is passed as hf_overrides only to a checkpoint that does not.
    """
    config = json.loads((Path(path) / "config.json").read_text())
    if not any(Path(path).glob("*.safetensors")):
        raise ValueError(f"{path} has no safetensors weights")
    if config.get("model_type") == "dory":
        return dory_policy(variant, requested, window)
    declared = checkpoint_policy(config)
    expected = config_keys(window) if variant == "w64" else {POLICY_KEY: NATIVE}
    if requested == "auto":
        effective = declared or {POLICY_KEY: NATIVE}
        if effective != expected:
            hint = (" (an older export: run python -m training.kd.fix_config on it, or pass --kv-policy shared_last)"
                    if variant == "w64" and declared is None else "")
            raise ValueError(f"{path} declares {effective}, but --variant {variant} needs {expected}{hint}")
        return effective, None
    forced = config_keys(window) if requested == SHARED else {POLICY_KEY: NATIVE}
    if forced != expected:
        raise ValueError(f"--kv-policy {requested} contradicts --variant {variant}")
    if declared is None:
        return forced, forced
    if declared != forced:
        raise ValueError(f"{path} declares {declared}; refusing to override it with {forced}")
    return forced, None


def dory_policy(variant, requested="auto", window=64):
    """(KV policy, hf_overrides) of Dory for a trace variant: the pinned checkpoint declares no policy,
    so the fork's dory_kv_policy overrides are recorded as the policy and always passed."""
    from vllm.v1.spec_decode.twodsd import DORY_WINDOW, dory_kv_policy

    if variant == "w64" and window != DORY_WINDOW:
        raise ValueError(f"Dory shares with W = {DORY_WINDOW}, not {window}")
    if requested not in ("auto", SHARED if variant == "w64" else NATIVE):
        raise ValueError(f"--kv-policy {requested} contradicts --variant {variant}")
    overrides = dory_kv_policy(DORY_SHARING[variant])
    return overrides, overrides


def compilation_config(family):
    """vLLM compilation of the trace engine: Dory compiles (VLLM_COMPILE), the others CUDA graphs only."""
    if family == "dory":
        from vllm.v1.spec_decode.twodsd import COMPILED

        return dict(COMPILED)
    if family not in ("ouro", "nanbeige"):
        raise NotImplementedError(f"The fork's engine cannot generate traces for family {family!r}")
    return dict(GRAPH_ONLY)


def runtime_options(budget, max_num_seqs, hf_overrides=None, compilation=None):
    options = {"tensor_parallel_size": 1, "max_model_len": budget, "max_num_seqs": max_num_seqs,
               "max_num_batched_tokens": budget, "gpu_memory_utilization": 0.92, "enforce_eager": False,
               "enable_prefix_caching": False, "enable_chunked_prefill": False, "dtype": "bfloat16",
               "model_impl": "vllm", "generation_config": "vllm",
               "compilation_config": dict(compilation or GRAPH_ONLY),
               "disable_hybrid_kv_cache_manager": False}
    if hf_overrides:
        options["hf_overrides"] = dict(hf_overrides)
    return options


def queue_dir(out):
    return Path(out) / "queue"


def load_settings(out):
    return json.loads((queue_dir(out) / "init.json").read_text())["settings"]


def render(settings, rows):
    """Prompt token IDs per pool row for this target's tokenizer and chat protocol."""
    family = registry.family(settings["model"])
    path = Path(settings["target_path"])
    tokenizer = load_tokenizer(path)
    if family == "ouro":
        manifest = json.loads((Path(settings["prompts"]) / "manifest.json").read_text())
        if file_sha(path / "tokenizer.json") != manifest["tokenizer"]["tokenizer_json_sha256"]:
            raise RuntimeError("the prompt pool was rendered with a different Ouro tokenizer")
        return {r["id"]: r["prompt_ids"] for r in rows}, {"rule": "pool prompt_ids (Ouro, enable_thinking)"}
    # The benchmark rows of the eval pool hold only Ouro-rendered IDs: one user turn and, for EvalPlus
    # code, an assistant prefix. Decode them and keep that structure.
    ouro = None
    out = {}
    for r in rows:
        if "prompt" in r:
            user, prefix = r["prompt"], ""
        else:
            if ouro is None:
                ouro = load_tokenizer(registry.resolve(settings["ouro_tokenizer"],
                                                       allow_patterns=registry.TOKENIZER_FILES))
            user, prefix = ouro_turns(ouro, r["prompt_ids"])
        out[r["id"]] = render_native(tokenizer, family, user, prefix)
    return out, {"rule": "native chat template, family system turn, enable_thinking; benchmark rows "
                         "re-rendered from their decoded Ouro user turn and assistant prefix",
                 "system": system_messages(family)}


def init(out, settings):
    """Pending work = greedy and selected sampled requests minus finished outputs, in pool order."""
    out = Path(out)
    prompts = Path(settings["prompts"])
    rows = [r for pool in settings["pools"] for r in read_jsonl(prompts / f"{pool}.jsonl")]
    prompt_ids, rendering = render(settings, rows)
    done = {r["id"] for path in (out / "raw").glob("*.jsonl") for r in read_jsonl_partial(path)}
    budget = settings["budget"]
    sampling = SAMPLING[registry.family(settings["model"])]
    items = []
    for r in rows:
        base = {**{k: r[k] for k in ("pool", "source", "domain", "origin")}, "prompt_id": r["id"],
                "prompt_ids": prompt_ids[r["id"]]}
        items.append({**base, "id": r["id"], "sampling": None})
        if unit(f"sampled:{r['id']}") < settings["sampled_fraction"]:
            setting = sampling[int(unit(f"setting:{r['id']}") * len(sampling))]
            items.append({**base, "id": f"{r['id']}#sampled", "sampling": {**setting, "seed": int(unit(r["id"]) * 2**31)}})
    if any(len(i["prompt_ids"]) >= budget for i in items):
        raise RuntimeError("A prompt exhausts the generation budget")
    requests = [{k: i[k] for k in ("id", "pool", "prompt_id", "sampling")} for i in items]
    items = [i for i in items if i["id"] not in done]
    queue = queue_dir(out)
    queue.mkdir(parents=True, exist_ok=True)
    with locked(queue):
        (queue / "requests.jsonl").write_text("".join(json.dumps(r) + "\n" for r in requests))
        (queue / "pending.jsonl").write_text("".join(json.dumps(i) + "\n" for i in items))
        (queue / "state.json").write_text(json.dumps({"next": 0}))
        (queue / "init.json").write_text(json.dumps({
            "settings": settings, "rendering": rendering, "sampling_settings": sampling,
            "loop_stop": {"window": LOOP_WINDOW, "ngram": LOOP_NGRAM, "min_unique": LOOP_MIN_UNIQUE,
                          "stride": LOOP_STRIDE},
            "pending": len(items), "pending_sampled": sum(i["sampling"] is not None for i in items), "done": len(done),
            "pool_sha256": {p: file_sha(prompts / f"{p}.jsonl") for p in settings["pools"]}}, indent=1))
    for stop in queue.glob("stop*"):
        stop.unlink()
    print(json.dumps({"model": settings["model"], "pending": len(items), "done": len(done)}), flush=True)


def claim(queue, pending, count):
    with locked(queue):
        state = json.loads((queue / "state.json").read_text())
        start = state["next"]
        state["next"] = min(len(pending), start + count)
        (queue / "state.json").write_text(json.dumps(state))
    return pending[start:state["next"]]


@contextmanager
def held(path):
    """Exclusive non-blocking flock on path for the block; fails at once if another process holds it."""
    with Path(path).open("a+") as handle:
        fcntl.flock(handle, fcntl.LOCK_EX | fcntl.LOCK_NB)
        yield


def worker(out, gpu, max_num_seqs, refill):
    from vllm import LLM, SamplingParams
    from vllm.sampling_params import RequestOutputKind

    # Imported by module name so that the engine process can unpickle the RPC by reference.
    from training.drafter.traces import worker_cache_layout as cache_layout

    settings = load_settings(out)
    model, variant, budget = settings["model"], settings["variant"], settings["budget"]
    path = Path(settings["target_path"])
    policy, overrides = target_policy(path, variant, settings["kv_policy"], settings["window"])
    queue = queue_dir(out)
    out_dir = Path(out) / "raw"
    out_dir.mkdir(parents=True, exist_ok=True)
    (queue / "workers").mkdir(exist_ok=True)
    tokenizer = load_tokenizer(path)
    eos = eos_ids(tokenizer, path)
    runtime = runtime_options(budget, max_num_seqs, overrides, compilation_config(registry.family(model)))
    config_sha = file_sha(path / "config.json")
    with ExitStack() as stack:
        stack.enter_context(held(queue / "workers" / f"gpu{gpu}.lock"))
        if settings["gpu_lock_dir"]:
            stack.enter_context(held(Path(settings["gpu_lock_dir"]) / f"2dsd-gpu{gpu}.lock"))
        llm = LLM(model=str(path), tokenizer=str(path), trust_remote_code=True, seed=0, **runtime)
        engine = llm.llm_engine
        layout = llm.collective_rpc(cache_layout)[0]
        cache = engine.vllm_config.cache_config
        usable = cache.num_gpu_blocks - 2
        engine_version = __import__("vllm").__version__
        pending = read_jsonl_partial(queue / "pending.jsonl")
        print(json.dumps({"gpu": gpu, "model": model, "budget": budget, "cache_layout": layout,
                          "block_size": cache.block_size, "usable_blocks": usable}), flush=True)
        # request id -> (item, reserved blocks, LoopWatch over the generated ids)
        active, reserved, stopping, exhausted, waiting = {}, 0, False, False, []
        started = last = time.monotonic()
        tokens = finished = loops = 0

        def save(sink, item, ids, reason, onset=None, generated=None):
            nonlocal tokens, finished
            record = {**item, "model": model, "target": settings["target"], "variant": variant,
                      "target_config_sha256": config_sha, "kv_policy": policy,
                      "output_ids": ids, "finish_reason": reason, "max_total_tokens": budget,
                      "loop_onset": onset, "generated_tokens": len(ids) if generated is None else generated,
                      "engine": f"vllm {engine_version}", "compile_mode": runtime["compilation_config"]["mode"],
                      "saved_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())}
            sink.write(json.dumps(record) + "\n")
            sink.flush()
            tokens += record["generated_tokens"]
            finished += 1

        with (out_dir / f"gpu{gpu}.jsonl").open("a") as sink:
            while True:
                if not stopping and ((queue / "stop").exists() or (queue / f"stop-gpu{gpu}").exists()):
                    stopping = True
                if not stopping and not exhausted and not waiting and len(active) <= max_num_seqs - refill:
                    waiting = claim(queue, pending, refill)
                    exhausted = not waiting
                while waiting and not stopping and len(active) < max_num_seqs:
                    item = waiting[0]
                    room = budget - len(item["prompt_ids"])
                    need = reserved_blocks({"prompt_tokens": len(item["prompt_ids"]), "max_new_tokens": room},
                                           layout, cache.block_size)
                    if need > usable:
                        raise RuntimeError("One request's full budget exceeds the KV allocation")
                    if reserved + need > usable:
                        break
                    waiting.pop(0)
                    s = item["sampling"] or {"temperature": 0.0, "top_p": 1.0, "top_k": 0, "seed": None}
                    params = SamplingParams(temperature=s["temperature"], top_p=s["top_p"], top_k=s["top_k"],
                                            seed=s["seed"], max_tokens=room, stop_token_ids=eos, ignore_eos=False,
                                            skip_special_tokens=False, detokenize=False,
                                            output_kind=RequestOutputKind.DELTA)
                    engine.add_request(item["id"], {"prompt_token_ids": item["prompt_ids"]}, params)
                    active[item["id"]] = (item, need, LoopWatch())
                    reserved += need
                if (stopping or exhausted) and not active and not waiting:
                    break
                if stopping and not active:
                    break
                aborted = []
                for output in engine.step():
                    entry = active.get(output.request_id)
                    if entry is None:
                        continue  # a delta after the request was stopped for looping
                    item, need, watch = entry
                    completion = output.outputs[0]
                    onset = watch.extend(completion.token_ids)
                    if onset is not None:  # also in the final delta (EOS or the length cap)
                        if not output.finished:
                            aborted.append(output.request_id)
                        del active[output.request_id]
                        reserved -= need
                        loops += 1
                        save(sink, item, watch.ids[:onset], "loop", onset, len(watch.ids))
                    elif output.finished:
                        del active[output.request_id]
                        reserved -= need
                        save(sink, item, watch.ids, completion.finish_reason)
                if aborted:
                    engine.abort_request(aborted)
                if time.monotonic() - last >= 60:
                    elapsed = time.monotonic() - started
                    live = sum(len(e[2].ids) for e in active.values())
                    print(json.dumps({"gpu": gpu, "finished": finished, "loop_stopped": loops, "active": len(active),
                                      "reserved_blocks": reserved, "generated_tokens": tokens + live,
                                      "tok_per_s": round((tokens + live) / elapsed), "elapsed_s": round(elapsed)}),
                          flush=True)
                    last = time.monotonic()
        engine.engine_core.shutdown()


def running_workers(out):
    """Workers of this queue (GPUs, or the server clients of traces_remote) that still hold their lock."""
    busy = []
    for path in sorted((queue_dir(out) / "workers").glob("*.lock")):
        try:
            with held(path):
                pass
        except BlockingIOError:
            busy.append(path.stem)
    return busy


def requeue(out):
    """Re-queue claimed but unfinished requests; only safe once no worker of this queue is running."""
    busy = running_workers(out)
    if busy:
        raise RuntimeError(f"Workers of this queue are still running: {busy}")
    init(out, load_settings(out))


def worker_env(gpu):
    path = os.environ.get("PYTHONPATH")
    # torch.compile and FlashInfer JIT builds call the venv's ninja; the venv may be used without activation.
    tools = f"{Path(sys.executable).parent}{os.pathsep}{os.environ.get('PATH', '')}"
    return dict(os.environ, PATH=tools, CUDA_VISIBLE_DEVICES=str(gpu), VLLM_USE_V2_MODEL_RUNNER="0",
                VLLM_USE_FLASHINFER_SAMPLER="0", TOKENIZERS_PARALLELISM="false", OMP_NUM_THREADS="4",
                VLLM_ALLOW_INSECURE_SERIALIZATION="1",  # the cache-layout RPC sends a callable
                PYTHONPATH=str(registry.ROOT) + (os.pathsep + path if path else ""))


def launch(out, gpus, max_num_seqs, refill):
    out = Path(out)
    settings = load_settings(out)
    logs = out / "logs"
    logs.mkdir(parents=True, exist_ok=True)
    for gpu in gpus:
        (queue_dir(out) / f"stop-gpu{gpu}").unlink(missing_ok=True)
    for gpu in gpus:
        log = (logs / f"gpu{gpu}.log").open("a")
        command = [sys.executable, "-m", "training.drafter.traces", "worker", "--out", str(out.resolve()),
                   "--gpu", str(gpu), "--max-num-seqs", str(max_num_seqs or MAX_SEQS.get(settings["model"], 64)),
                   "--refill", str(refill)]
        subprocess.Popen(command, cwd=registry.ROOT, env=worker_env(gpu), stdout=log, stderr=subprocess.STDOUT,
                         start_new_session=True)
        print(f"gpu{gpu}: {settings['model']} -> {log.name}", flush=True)
        time.sleep(15)  # engines started together can race for the same distributed init port


def status(out):
    queue = queue_dir(out)
    state = json.loads((queue / "state.json").read_text())
    pending = len(read_jsonl_partial(queue / "pending.jsonl"))
    rows = [r for path in (Path(out) / "raw").glob("*.jsonl") for r in read_jsonl_partial(path)]
    by_pool = {}
    for r in rows:
        key = r["pool"] + ("/sampled" if r.get("sampling") else "")
        p = by_pool.setdefault(key, {"traces": 0, "length": 0, "loop": 0, "tokens": 0})
        p["traces"] += 1
        p["length"] += r["finish_reason"] == "length"
        p["loop"] += r["finish_reason"] == "loop"
        p["tokens"] += len(r["output_ids"])
    print(json.dumps({"claimed": state["next"], "queued": pending, "running": running_workers(out),
                      "finished": by_pool}, indent=1))


def collect(out, pools=None, allow_missing=False):
    """Write <pool>.jsonl in request order. allow_missing collects an unfinished queue (the traces that
    exist, with the count of missing ones in the manifest) instead of raising."""
    out = Path(out)
    pools = pools or load_settings(out)["pools"]
    new = {r["id"]: r for path in sorted((out / "raw").glob("*.jsonl")) for r in read_jsonl_partial(path)}
    requests = read_jsonl_partial(queue_dir(out) / "requests.jsonl")
    summary = {}
    for name in pools:
        ids = [r["id"] for r in requests if r["pool"] == name]
        missing = [i for i in ids if i not in new]
        if missing and not allow_missing:
            raise RuntimeError(f"{name}: {len(missing)} requests have no finished trace")
        ids = [i for i in ids if i in new]
        if not ids:
            continue
        rows = [{**new[i], "degenerate": is_degenerate(new[i]["output_ids"])} for i in ids]
        (out / f"{name}.jsonl").write_text("".join(json.dumps(r) + "\n" for r in rows))
        lengths = sorted(len(r["prompt_ids"]) + len(r["output_ids"]) for r in rows)
        summary[name] = {"traces": len(rows), "missing": len(missing),
                         "sampled": sum(bool(r.get("sampling")) for r in rows),
                         "degenerate": sum(r["degenerate"] for r in rows),
                         "length_capped": sum(r["finish_reason"] == "length" for r in rows),
                         "loop_stopped": sum(r["finish_reason"] == "loop" for r in rows),
                         "total_tokens_p50_p90_max": [lengths[len(lengths) // 2], lengths[int(len(lengths) * .9)],
                                                      lengths[-1]]}
    path = out / "manifest.json"
    merged = json.loads(path.read_text()) if path.exists() else {}
    path.write_text(json.dumps(merged | summary, indent=2) + "\n")
    print(json.dumps(summary, indent=1))


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    commands = parser.add_subparsers(dest="command", required=True)
    launch_p = commands.add_parser("launch", help="build the queue and start workers")
    launch_p.add_argument("--model", required=True, choices=registry.names())
    launch_p.add_argument("--variant", choices=registry.VARIANTS, default="w64")
    launch_p.add_argument("--target-path", help="local directory or HF repo id of the target "
                                                "(default: the repository in configs/models.json)")
    launch_p.add_argument("--target-name", help="target identifier recorded in every trace "
                                                "(default: the registry or HF id; <model>-<variant> for a local path)")
    launch_p.add_argument("--prompts", type=Path, required=True, help="prompt pool directory (<pool>.jsonl, manifest.json)")
    launch_p.add_argument("--budget", type=int, default=16384, help="prompt + output tokens")
    launch_p.add_argument("--sampled-fraction", type=float, default=0.25)
    launch_p.add_argument("--pools", nargs="+", choices=POOL_ORDER, default=list(POOL_ORDER))
    launch_p.add_argument("--kv-policy", choices=("auto", SHARED, NATIVE), default="auto",
                          help="auto: the checkpoint's config.json; otherwise force it on a checkpoint that lacks it")
    launch_p.add_argument("--window", type=int, default=64, help="shared window W of a w64 target")
    launch_p.add_argument("--ouro-tokenizer", default="ouro-1.4b-thinking",
                          help="decodes the Ouro-rendered benchmark rows of the eval pool for Nanbeige and Dory")
    launch_p.add_argument("--gpu-lock-dir", default=tempfile.gettempdir(),
                          help="directory of per-GPU lock files shared with other jobs ('' disables)")
    for name, sub in (("launch", launch_p), ("join", commands.add_parser("join", help="add workers"))):
        sub.add_argument("--gpus", type=int, nargs="+", required=True)
        sub.add_argument("--max-num-seqs", type=int, help="override the per-model concurrency cap")
        sub.add_argument("--refill", type=int, default=8)
    worker_p = commands.add_parser("worker", help="(internal) one GPU")
    worker_p.add_argument("--gpu", type=int, required=True)
    worker_p.add_argument("--max-num-seqs", type=int, required=True)
    worker_p.add_argument("--refill", type=int, default=8)
    commands.add_parser("status", help="progress")
    commands.add_parser("requeue", help="re-queue unfinished requests")
    collect_p = commands.add_parser("collect", help="write <pool>.jsonl and manifest.json")
    collect_p.add_argument("--pools", nargs="+", choices=POOL_ORDER)
    collect_p.add_argument("--allow-missing", action="store_true", help="collect an unfinished queue")
    for sub in commands.choices.values():
        sub.add_argument("--out", type=Path, required=True, help="trace directory of one model and variant")
    args = parser.parse_args(argv)
    if args.command == "launch":
        path = registry.resolve_target(args.model, args.variant, args.target_path)
        target_policy(path, args.variant, args.kv_policy, args.window)  # fail before building the queue
        settings = {"model": args.model, "variant": args.variant, "target_path": str(Path(path).resolve()),
                    "target": args.target_name or registry.label(args.target_path or args.model, args.variant)
                    or f"{args.model}-{args.variant}",
                    "prompts": str(args.prompts.resolve()), "budget": args.budget,
                    "pools": [p for p in POOL_ORDER if p in args.pools], "sampled_fraction": args.sampled_fraction,
                    "kv_policy": args.kv_policy, "window": args.window, "ouro_tokenizer": args.ouro_tokenizer,
                    "gpu_lock_dir": args.gpu_lock_dir}
        init(args.out, settings)
        launch(args.out, args.gpus, args.max_num_seqs, args.refill)
    elif args.command == "join":
        launch(args.out, args.gpus, args.max_num_seqs, args.refill)
    elif args.command == "worker":
        worker(args.out, args.gpu, args.max_num_seqs, args.refill)
    elif args.command == "status":
        status(args.out)
    elif args.command == "requeue":
        requeue(args.out)
    else:
        collect(args.out, args.pools and [p for p in POOL_ORDER if p in args.pools], args.allow_missing)


if __name__ == "__main__":
    main()
